import re
prose_keys={'summary','platform_strategy','claim','scope','note','size_claim','outcome','reason','reader_access','proof','count_note','verification','integration_implication','holdings','limitations','needs','blockers','unit'}
def polish(x,key=''):
 if isinstance(x,dict):return {k:polish(v,k) for k,v in x.items()}
 if isinstance(x,list):return [polish(v,key) for v in x]
 if isinstance(x,str) and key in prose_keys and 'http' not in x:
  x=re.sub(r'(?<=\d)(?=[A-Za-z])',' ',x)
  x=re.sub(r'(?<=[A-Za-z])(?=\d)',' ',x)
  x=re.sub(r',(?=[A-Za-z])',', ',x)
  x=re.sub(r';(?=[A-Za-z])','; ',x)
 return x
findings=polish(findings)
(D/'findings.json').write_text(json.dumps(findings,ensure_ascii=False,indent=2)+'\n')
